25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * AXI4-Stream Ethernet FCS checker
33	 */
34	module axis_eth_fcs_check
35	(
36	    input  wire        clk,
37	    input  wire        rst,
38	    
39	    /*
40	     * AXI input
41	     */
42	    input  wire [7:0]  s_axis_tdata,
43	    input  wire        s_axis_tvalid,
44	    output wire        s_axis_tready,
45	    input  wire        s_axis_tlast,
46	    input  wire        s_axis_tuser,
47	    
48	    /*
49	     * AXI output
50	     */
51	    output wire [7:0]  m_axis_tdata,
52	    output wire        m_axis_tvalid,
53	    input  wire        m_axis_tready,
54	    output wire        m_axis_tlast,
55	    output wire        m_axis_tuser,
56	
57	    /*
58	     * Status
59	     */
60	    output wire        busy,
61	    output wire        error_bad_fcs
62	);
63	
64	localparam [1:0]
65	    STATE_IDLE = 2'd0,
66	    STATE_PAYLOAD = 2'd1;
67	
68	reg [1:0] state_reg = STATE_IDLE, state_next;
69	
70	// datapath control signals
71	reg reset_crc;
72	reg update_crc;
73	reg shift_in;
74	reg shift_reset;
75	
76	reg [7:0] s_axis_tdata_d0 = 8'd0;
77	reg [7:0] s_axis_tdata_d1 = 8'd0;
78	reg [7:0] s_axis_tdata_d2 = 8'd0;
79	reg [7:0] s_axis_tdata_d3 = 8'd0;
80	
81	reg s_axis_tvalid_d0 = 1'b0;
82	reg s_axis_tvalid_d1 = 1'b0;
83	reg s_axis_tvalid_d2 = 1'b0;
84	reg s_axis_tvalid_d3 = 1'b0;
85	
86	reg busy_reg = 1'b0;
87	reg error_bad_fcs_reg = 1'b0, error_bad_fcs_next;
88	
89	reg s_axis_tready_reg = 1'b0, s_axis_tready_next;
90	
91	reg [31:0] crc_state = 32'hFFFFFFFF;
92	wire [31:0] crc_next;
93	
94	// internal datapath
95	reg [7:0] m_axis_tdata_int;
96	reg       m_axis_tvalid_int;
97	reg       m_axis_tready_int_reg = 1'b0;
98	reg       m_axis_tlast_int;
99	reg       m_axis_tuser_int;
100	wire      m_axis_tready_int_early;
101	
102	assign s_axis_tready = s_axis_tready_reg;
103	
104	assign busy = busy_reg;
105	assign error_bad_fcs = error_bad_fcs_reg;
106	
107	lfsr #(
108	    .LFSR_WIDTH(32),
109	    .LFSR_POLY(32'h4c11db7),
110	    .LFSR_CONFIG("GALOIS"),
111	    .LFSR_FEED_FORWARD(0),
112	    .REVERSE(1),
113	    .DATA_WIDTH(8),
114	    .STYLE("AUTO")
115	)
116	eth_crc_8 (
117	    .data_in(s_axis_tdata_d3),
118	    .state_in(crc_state),
119	    .data_out(),
120	    .state_out(crc_next)
121	);
122	
123	always @* begin
124	    state_next = STATE_IDLE;
125	
126	    reset_crc = 1'b0;
127	    update_crc = 1'b0;
128	    shift_in = 1'b0;
129	    shift_reset = 1'b0;
130	
131	    s_axis_tready_next = 1'b0;
132	
133	    m_axis_tdata_int = 8'd0;
134	    m_axis_tvalid_int = 1'b0;
135	    m_axis_tlast_int = 1'b0;
136	    m_axis_tuser_int = 1'b0;
137	
138	    error_bad_fcs_next = 1'b0;
139	
140	    case (state_reg)
141	        STATE_IDLE: begin
142	            // idle state - wait for data
143	            s_axis_tready_next = m_axis_tready_int_early;
144	            reset_crc = 1'b1;
145	
146	            m_axis_tdata_int = s_axis_tdata_d3;
147	            m_axis_tvalid_int = s_axis_tvalid_d3 && s_axis_tvalid;
148	            m_axis_tlast_int = 1'b0;
149	            m_axis_tuser_int = 1'b0;
150	
151	            if (s_axis_tready && s_axis_tvalid) begin
152	                shift_in = 1'b1;
153	
154	                if (s_axis_tvalid_d3) begin
155	                    reset_crc = 1'b0;
156	                    update_crc = 1'b1;
157	                    if (s_axis_tlast) begin
158	                        shift_reset = 1'b1;
159	                        reset_crc = 1'b1;
160	                        m_axis_tlast_int = 1'b1;
161	                        m_axis_tuser_int = s_axis_tuser;
162	                        if ({s_axis_tdata, s_axis_tdata_d0, s_axis_tdata_d1, s_axis_tdata_d2} != ~crc_next) begin
163	                            m_axis_tuser_int = 1'b1;
164	                            error_bad_fcs_next = 1'b1;
165	                        end
166	                        s_axis_tready_next = m_axis_tready_int_early;
167	                        state_next = STATE_IDLE;
168	                    end else begin
169	                        state_next = STATE_PAYLOAD;
170	                    end
171	                end else begin
172	                    state_next = STATE_IDLE;
173	                end
174	            end else begin
175	                state_next = STATE_IDLE;
176	            end
177	        end
178	        STATE_PAYLOAD: begin
179	            // transfer payload
180	            s_axis_tready_next = m_axis_tready_int_early;
181	
182	            m_axis_tdata_int = s_axis_tdata_d3;
183	            m_axis_tvalid_int = s_axis_tvalid_d3 && s_axis_tvalid;
184	            m_axis_tlast_int = 1'b0;
185	            m_axis_tuser_int = 1'b0;
186	
187	            if (s_axis_tready && s_axis_tvalid) begin
188	                shift_in = 1'b1;
189	                update_crc = 1'b1;
190	                if (s_axis_tlast) begin
191	                    shift_reset = 1'b1;
192	                    reset_crc = 1'b1;
193	                    m_axis_tlast_int = 1'b1;
194	                    m_axis_tuser_int = s_axis_tuser;
195	                    if ({s_axis_tdata, s_axis_tdata_d0, s_axis_tdata_d1, s_axis_tdata_d2} != ~crc_next) begin
196	                        m_axis_tuser_int = 1'b1;
197	                        error_bad_fcs_next = 1'b1;
198	                    end
199	                    s_axis_tready_next = m_axis_tready_int_early;
200	                    state_next = STATE_IDLE;
201	                end else begin
202	                    state_next = STATE_PAYLOAD;
203	                end
204	            end else begin
205	                state_next = STATE_PAYLOAD;
206	            end
207	        end
208	    endcase
209	end
210	
211	always @(posedge clk) begin
212	    if (rst) begin
213	        state_reg <= STATE_IDLE;
214	
215	        s_axis_tready_reg <= 1'b0;
216	
217	        busy_reg <= 1'b0;
218	        error_bad_fcs_reg <= 1'b0;
219	
220	        s_axis_tvalid_d0 <= 1'b0;
221	        s_axis_tvalid_d1 <= 1'b0;
222	        s_axis_tvalid_d2 <= 1'b0;
223	        s_axis_tvalid_d3 <= 1'b0;
224	
225	        crc_state <= 32'hFFFFFFFF;
226	    end else begin
227	        state_reg <= state_next;
228	
229	        s_axis_tready_reg <= s_axis_tready_next;
230	
231	        busy_reg <= state_next != STATE_IDLE;
232	        error_bad_fcs_reg <= error_bad_fcs_next;
233	
234	        // datapath
235	        if (reset_crc) begin
236	            crc_state <= 32'hFFFFFFFF;
237	        end else if (update_crc) begin
238	            crc_state <= crc_next;
239	        end
240	
241	        if (shift_reset) begin
242	            s_axis_tvalid_d0 <= 1'b0;
243	            s_axis_tvalid_d1 <= 1'b0;
244	            s_axis_tvalid_d2 <= 1'b0;
245	            s_axis_tvalid_d3 <= 1'b0;
246	        end else if (shift_in) begin
247	            s_axis_tvalid_d0 <= s_axis_tvalid;
248	            s_axis_tvalid_d1 <= s_axis_tvalid_d0;
249	            s_axis_tvalid_d2 <= s_axis_tvalid_d1;
250	            s_axis_tvalid_d3 <= s_axis_tvalid_d2;
251	        end
252	    end
253	
254	    if (shift_in) begin
255	        s_axis_tdata_d0 <= s_axis_tdata;
256	        s_axis_tdata_d1 <= s_axis_tdata_d0;
257	        s_axis_tdata_d2 <= s_axis_tdata_d1;
258	        s_axis_tdata_d3 <= s_axis_tdata_d2;
259	    end
260	end
261	
262	// output datapath logic
263	reg [7:0] m_axis_tdata_reg = 8'd0;
264	reg       m_axis_tvalid_reg = 1'b0, m_axis_tvalid_next;
265	reg       m_axis_tlast_reg = 1'b0;
266	reg       m_axis_tuser_reg = 1'b0;
267	
268	reg [7:0] temp_m_axis_tdata_reg = 8'd0;
269	reg       temp_m_axis_tvalid_reg = 1'b0, temp_m_axis_tvalid_next;
270	reg       temp_m_axis_tlast_reg = 1'b0;
271	reg       temp_m_axis_tuser_reg = 1'b0;
272	
273	// datapath control
274	reg store_axis_int_to_output;
275	reg store_axis_int_to_temp;
276	reg store_axis_temp_to_output;
277	
278	assign m_axis_tdata = m_axis_tdata_reg;
279	assign m_axis_tvalid = m_axis_tvalid_reg;
280	assign m_axis_tlast = m_axis_tlast_reg;
281	assign m_axis_tuser = m_axis_tuser_reg;
282	
283	// enable ready input next cycle if output is ready or if both output registers are empty
284	assign m_axis_tready_int_early = m_axis_tready || (!temp_m_axis_tvalid_reg && !m_axis_tvalid_reg);
285	
286	always @* begin
287	    // transfer sink ready state to source
288	    m_axis_tvalid_next = m_axis_tvalid_reg;
289	    temp_m_axis_tvalid_next = temp_m_axis_tvalid_reg;
290	
291	    store_axis_int_to_output = 1'b0;
292	    store_axis_int_to_temp = 1'b0;
293	    store_axis_temp_to_output = 1'b0;
294	    
295	    if (m_axis_tready_int_reg) begin
296	        // input is ready
297	        if (m_axis_tready || !m_axis_tvalid_reg) begin
298	            // output is ready or currently not valid, transfer data to output
299	            m_axis_tvalid_next = m_axis_tvalid_int;
300	            store_axis_int_to_output = 1'b1;
301	        end else begin
302	            // output is not ready, store input in temp
303	            temp_m_axis_tvalid_next = m_axis_tvalid_int;
304	            store_axis_int_to_temp = 1'b1;
305	        end
306	    end else if (m_axis_tready) begin
307	        // input is not ready, but output is ready
308	        m_axis_tvalid_next = temp_m_axis_tvalid_reg;
309	        temp_m_axis_tvalid_next = 1'b0;
310	        store_axis_temp_to_output = 1'b1;
311	    end
312	end
313	
314	always @(posedge clk) begin
315	    m_axis_tvalid_reg <= m_axis_tvalid_next;
316	    m_axis_tready_int_reg <= m_axis_tready_int_early;
317	    temp_m_axis_tvalid_reg <= temp_m_axis_tvalid_next;
318	
319	    // datapath
320	    if (store_axis_int_to_output) begin
321	        m_axis_tdata_reg <= m_axis_tdata_int;
322	        m_axis_tlast_reg <= m_axis_tlast_int;
323	        m_axis_tuser_reg <= m_axis_tuser_int;
324	    end else if (store_axis_temp_to_output) begin
325	        m_axis_tdata_reg <= temp_m_axis_tdata_reg;
326	        m_axis_tlast_reg <= temp_m_axis_tlast_reg;
327	        m_axis_tuser_reg <= temp_m_axis_tuser_reg;
328	    end
329	
330	    if (store_axis_int_to_temp) begin
331	        temp_m_axis_tdata_reg <= m_axis_tdata_int;
332	        temp_m_axis_tlast_reg <= m_axis_tlast_int;
333	        temp_m_axis_tuser_reg <= m_axis_tuser_int;
334	    end
335	
336	    if (rst) begin
337	        m_axis_tvalid_reg <= 1'b0;
338	        m_axis_tready_int_reg <= 1'b0;
339	        temp_m_axis_tvalid_reg <= 1'b0;
340	    end
341	end
342	
343	endmodule
344	
345	`resetall
346

