47	    input  wire        s_axis_tvalid,
48	    output wire        s_axis_tready,
49	    input  wire        s_axis_tlast,
50	    input  wire        s_axis_tuser,
51	    
52	    /*
53	     * AXI output
54	     */
55	    output wire [7:0]  m_axis_tdata,
56	    output wire        m_axis_tvalid,
57	    input  wire        m_axis_tready,
58	    output wire        m_axis_tlast,
59	    output wire        m_axis_tuser,
60	
61	    /*
62	     * Status
63	     */
64	    output wire        busy
65	);
66	
67	localparam [1:0]
68	    STATE_IDLE = 2'd0,
69	    STATE_PAYLOAD = 2'd1,
70	    STATE_PAD = 2'd2,
71	    STATE_FCS = 2'd3;
72	
73	reg [1:0] state_reg = STATE_IDLE, state_next;
74	
75	// datapath control signals
76	reg reset_crc;
77	reg update_crc;
78	
79	reg [15:0] frame_ptr_reg = 16'd0, frame_ptr_next;
80	
81	reg busy_reg = 1'b0;
82	
83	reg s_axis_tready_reg = 1'b0, s_axis_tready_next;
84	
85	reg [31:0] crc_state = 32'hFFFFFFFF;
86	wire [31:0] crc_next;
87	
88	// internal datapath
89	reg [7:0] m_axis_tdata_int;
90	reg       m_axis_tvalid_int;
91	reg       m_axis_tready_int_reg = 1'b0;
92	reg       m_axis_tlast_int;
93	reg       m_axis_tuser_int;
94	wire      m_axis_tready_int_early;
95	
96	assign s_axis_tready = s_axis_tready_reg;
97	
98	assign busy = busy_reg;
99	
100	lfsr #(
101	    .LFSR_WIDTH(32),
102	    .LFSR_POLY(32'h4c11db7),
103	    .LFSR_CONFIG("GALOIS"),
104	    .LFSR_FEED_FORWARD(0),
105	    .REVERSE(1),
106	    .DATA_WIDTH(8),
107	    .STYLE("AUTO")
108	)
109	eth_crc_8 (
110	    .data_in(m_axis_tdata_int),
111	    .state_in(crc_state),
112	    .data_out(),
113	    .state_out(crc_next)
114	);
115	
116	always @* begin
117	    state_next = STATE_IDLE;
118	
119	    reset_crc = 1'b0;
120	    update_crc = 1'b0;
121	
122	    frame_ptr_next = frame_ptr_reg;
123	
124	    s_axis_tready_next = 1'b0;
125	
126	    m_axis_tdata_int = 8'd0;
127	    m_axis_tvalid_int = 1'b0;
128	    m_axis_tlast_int = 1'b0;
129	    m_axis_tuser_int = 1'b0;
130	
131	    case (state_reg)
132	        STATE_IDLE: begin
133	            // idle state - wait for data
134	            s_axis_tready_next = m_axis_tready_int_early;
135	            frame_ptr_next = 16'd0;
136	            reset_crc = 1'b1;
137	
138	            m_axis_tdata_int = s_axis_tdata;
139	            m_axis_tvalid_int = s_axis_tvalid;
140	            m_axis_tlast_int = 1'b0;
141	            m_axis_tuser_int = 1'b0;
142	
143	            if (s_axis_tready && s_axis_tvalid) begin
144	                frame_ptr_next = 16'd1;
145	                reset_crc = 1'b0;
146	                update_crc = 1'b1;
147	                if (s_axis_tlast) begin
148	                    if (s_axis_tuser) begin
149	                        m_axis_tlast_int = 1'b1;
150	                        m_axis_tuser_int = 1'b1;
151	                        reset_crc = 1'b1;
152	                        frame_ptr_next = 16'd0;
153	                        state_next = STATE_IDLE;
154	                    end else begin
155	                        s_axis_tready_next = 1'b0;
156	                        if (ENABLE_PADDING && frame_ptr_reg < MIN_FRAME_LENGTH-5) begin
157	                            state_next = STATE_PAD;
158	                        end else begin
159	                            frame_ptr_next = 16'd0;
160	                            state_next = STATE_FCS;
161	                        end
162	                    end
163	                end else begin
164	                    state_next = STATE_PAYLOAD;
165	                end
166	            end else begin
167	                state_next = STATE_IDLE;
168	            end
169	        end
170	        STATE_PAYLOAD: begin
171	            // transfer payload
172	            s_axis_tready_next = m_axis_tready_int_early;
173	
174	            m_axis_tdata_int = s_axis_tdata;
175	            m_axis_tvalid_int = s_axis_tvalid;
176	            m_axis_tlast_int = 1'b0;
177	            m_axis_tuser_int = 1'b0;
178	
179	            if (s_axis_tready && s_axis_tvalid) begin
180	                frame_ptr_next = frame_ptr_reg + 16'd1;
181	                update_crc = 1'b1;
182	                if (s_axis_tlast) begin
183	                    if (s_axis_tuser) begin
184	                        m_axis_tlast_int = 1'b1;
185	                        m_axis_tuser_int = 1'b1;
186	                        reset_crc = 1'b1;
187	                        frame_ptr_next = 16'd0;
188	                        state_next = STATE_IDLE;
189	                    end else begin
190	                        s_axis_tready_next = 1'b0;
191	                        if (ENABLE_PADDING && frame_ptr_reg < MIN_FRAME_LENGTH-5) begin
192	                            state_next = STATE_PAD;
193	                        end else begin
194	                            frame_ptr_next = 16'd0;
195	                            state_next = STATE_FCS;
196	                        end
197	                    end
198	                end else begin
199	                    state_next = STATE_PAYLOAD;
200	                end
201	            end else begin
202	                state_next = STATE_PAYLOAD;
203	            end
204	        end
205	        STATE_PAD: begin
206	            // insert padding
207	            s_axis_tready_next = 1'b0;
208	
209	            m_axis_tdata_int = 8'd0;
210	            m_axis_tvalid_int = 1'b1;
211	            m_axis_tlast_int = 1'b0;
212	            m_axis_tuser_int = 1'b0;
213	
214	            if (m_axis_tready_int_reg) begin
215	                frame_ptr_next = frame_ptr_reg + 16'd1;
216	                update_crc = 1'b1;
217	                if (frame_ptr_reg < MIN_FRAME_LENGTH-5) begin
218	                    state_next = STATE_PAD;
219	                end else begin
220	                    frame_ptr_next = 16'd0;
221	                    state_next = STATE_FCS;
222	                end
223	            end else begin
224	                state_next = STATE_PAD;
225	            end
226	        end
227	        STATE_FCS: begin
228	            // send FCS
229	            s_axis_tready_next = 1'b0;
230	
231	            case (frame_ptr_reg)
232	                2'd0: m_axis_tdata_int = ~crc_state[7:0];
233	                2'd1: m_axis_tdata_int = ~crc_state[15:8];
234	                2'd2: m_axis_tdata_int = ~crc_state[23:16];
235	                2'd3: m_axis_tdata_int = ~crc_state[31:24];
236	            endcase
237	            m_axis_tvalid_int = 1'b1;
238	            m_axis_tlast_int = 1'b0;
239	            m_axis_tuser_int = 1'b0;
240	
241	            if (m_axis_tready_int_reg) begin
242	                frame_ptr_next = frame_ptr_reg + 16'd1;
243	
244	                if (frame_ptr_reg < 16'd3) begin
245	                    state_next = STATE_FCS;
246	                end else begin
247	                    reset_crc = 1'b1;
248	                    frame_ptr_next = 16'd0;
249	                    m_axis_tlast_int = 1'b1;
250	                    s_axis_tready_next = m_axis_tready_int_early;
251	                    state_next = STATE_IDLE;
252	                end
253	            end else begin
254	                state_next = STATE_FCS;
255	            end
256	        end
257	    endcase
258	end
259	
260	always @(posedge clk) begin
261	    if (rst) begin
262	        state_reg <= STATE_IDLE;
263	        
264	        frame_ptr_reg <= 1'b0;
265	        
266	        s_axis_tready_reg <= 1'b0;
267	
268	        busy_reg <= 1'b0;
269	
270	        crc_state <= 32'hFFFFFFFF;
271	    end else begin
272	        state_reg <= state_next;
273	
274	        frame_ptr_reg <= frame_ptr_next;
275	
276	        s_axis_tready_reg <= s_axis_tready_next;
277	
278	        busy_reg <= state_next != STATE_IDLE;
279	
280	        // datapath
281	        if (reset_crc) begin
282	            crc_state <= 32'hFFFFFFFF;
283	        end else if (update_crc) begin
284	            crc_state <= crc_next;
285	        end
286	    end
287	end
288	
289	// output datapath logic
290	reg [7:0] m_axis_tdata_reg = 8'd0;
291	reg       m_axis_tvalid_reg = 1'b0, m_axis_tvalid_next;
292	reg       m_axis_tlast_reg = 1'b0;
293	reg       m_axis_tuser_reg = 1'b0;
294	
295	reg [7:0] temp_m_axis_tdata_reg = 8'd0;
296	reg       temp_m_axis_tvalid_reg = 1'b0, temp_m_axis_tvalid_next;
297	reg       temp_m_axis_tlast_reg = 1'b0;
298	reg       temp_m_axis_tuser_reg = 1'b0;
299	
300	// datapath control
301	reg store_axis_int_to_output;
302	reg store_axis_int_to_temp;
303	reg store_axis_temp_to_output;
304	
305	assign m_axis_tdata = m_axis_tdata_reg;
306	assign m_axis_tvalid = m_axis_tvalid_reg;
307	assign m_axis_tlast = m_axis_tlast_reg;
308	assign m_axis_tuser = m_axis_tuser_reg;
309	
310	// enable ready input next cycle if output is ready or if both output registers are empty
311	assign m_axis_tready_int_early = m_axis_tready || (!temp_m_axis_tvalid_reg && !m_axis_tvalid_reg);
312	
313	always @* begin
314	    // transfer sink ready state to source
315	    m_axis_tvalid_next = m_axis_tvalid_reg;
316	    temp_m_axis_tvalid_next = temp_m_axis_tvalid_reg;
317	
318	    store_axis_int_to_output = 1'b0;
319	    store_axis_int_to_temp = 1'b0;
320	    store_axis_temp_to_output = 1'b0;
321	    
322	    if (m_axis_tready_int_reg) begin
323	        // input is ready
324	        if (m_axis_tready || !m_axis_tvalid_reg) begin
325	            // output is ready or currently not valid, transfer data to output
326	            m_axis_tvalid_next = m_axis_tvalid_int;
327	            store_axis_int_to_output = 1'b1;
328	        end else begin
329	            // output is not ready, store input in temp
330	            temp_m_axis_tvalid_next = m_axis_tvalid_int;
331	            store_axis_int_to_temp = 1'b1;
332	        end
333	    end else if (m_axis_tready) begin
334	        // input is not ready, but output is ready
335	        m_axis_tvalid_next = temp_m_axis_tvalid_reg;
336	        temp_m_axis_tvalid_next = 1'b0;
337	        store_axis_temp_to_output = 1'b1;
338	    end
339	end
340	
341	always @(posedge clk) begin
342	    m_axis_tvalid_reg <= m_axis_tvalid_next;
343	    m_axis_tready_int_reg <= m_axis_tready_int_early;
344	    temp_m_axis_tvalid_reg <= temp_m_axis_tvalid_next;
345	
346	    // datapath
347	    if (store_axis_int_to_output) begin
348	        m_axis_tdata_reg <= m_axis_tdata_int;
349	        m_axis_tlast_reg <= m_axis_tlast_int;
350	        m_axis_tuser_reg <= m_axis_tuser_int;
351	    end else if (store_axis_temp_to_output) begin
352	        m_axis_tdata_reg <= temp_m_axis_tdata_reg;
353	        m_axis_tlast_reg <= temp_m_axis_tlast_reg;
354	        m_axis_tuser_reg <= temp_m_axis_tuser_reg;
355	    end
356	
357	    if (store_axis_int_to_temp) begin
358	        temp_m_axis_tdata_reg <= m_axis_tdata_int;
359	        temp_m_axis_tlast_reg <= m_axis_tlast_int;
360	        temp_m_axis_tuser_reg <= m_axis_tuser_int;
361	    end
362	
363	    if (rst) begin
364	        m_axis_tvalid_reg <= 1'b0;
365	        m_axis_tready_int_reg <= 1'b0;
366	        temp_m_axis_tvalid_reg <= 1'b0;
367	    end
368	end
369	
370	endmodule
371	
