30	
31	/*
32	 * AXI4-Stream Ethernet FCS checker (64 bit datapath)
33	 */
34	module axis_eth_fcs_check_64
35	(
36	    input  wire        clk,
37	    input  wire        rst,
38	    
39	    /*
40	     * AXI input
41	     */
42	    input  wire [63:0] s_axis_tdata,
43	    input  wire [7:0]  s_axis_tkeep,
44	    input  wire        s_axis_tvalid,
45	    output wire        s_axis_tready,
46	    input  wire        s_axis_tlast,
47	    input  wire        s_axis_tuser,
48	    
49	    /*
50	     * AXI output
51	     */
52	    output wire [63:0] m_axis_tdata,
53	    output wire [7:0]  m_axis_tkeep,
54	    output wire        m_axis_tvalid,
55	    input  wire        m_axis_tready,
56	    output wire        m_axis_tlast,
57	    output wire        m_axis_tuser,
58	
59	    /*
60	     * Status
61	     */
62	    output wire        busy,
63	    output wire        error_bad_fcs
64	);
65	
66	localparam [1:0]
67	    STATE_IDLE = 2'd0,
68	    STATE_PAYLOAD = 2'd1,
69	    STATE_LAST = 2'd2;
70	
71	reg [1:0] state_reg = STATE_IDLE, state_next;
72	
73	// datapath control signals
74	reg reset_crc;
75	reg update_crc;
76	reg shift_in;
77	reg shift_reset;
78	
79	reg [7:0] last_cycle_tkeep_reg = 8'd0, last_cycle_tkeep_next;
80	reg last_cycle_tuser_reg = 1'b0, last_cycle_tuser_next;
81	
82	reg [63:0] s_axis_tdata_d0 = 64'd0;
83	reg [7:0] s_axis_tkeep_d0 = 8'd0;
84	reg s_axis_tvalid_d0 = 1'b0;
85	reg s_axis_tuser_d0 = 1'b0;
86	
87	reg busy_reg = 1'b0;
88	reg error_bad_fcs_reg = 1'b0, error_bad_fcs_next;
89	
90	reg s_axis_tready_reg = 1'b0, s_axis_tready_next;
91	
92	reg [31:0] crc_state = 32'hFFFFFFFF;
93	reg [31:0] crc_state3 = 32'hFFFFFFFF;
94	
95	wire [31:0] crc_next0;
96	wire [31:0] crc_next1;
97	wire [31:0] crc_next2;
98	wire [31:0] crc_next3;
99	wire [31:0] crc_next7;
100	
101	wire crc_valid0 = crc_next0 == ~32'h2144df1c;
102	wire crc_valid1 = crc_next1 == ~32'h2144df1c;
103	wire crc_valid2 = crc_next2 == ~32'h2144df1c;
104	wire crc_valid3 = crc_next3 == ~32'h2144df1c;
105	
106	// internal datapath
107	reg [63:0] m_axis_tdata_int;
108	reg [7:0]  m_axis_tkeep_int;
109	reg        m_axis_tvalid_int;
110	reg        m_axis_tready_int_reg = 1'b0;
111	reg        m_axis_tlast_int;
112	reg        m_axis_tuser_int;
113	wire       m_axis_tready_int_early;
114	
115	assign s_axis_tready = s_axis_tready_reg;
116	
117	assign busy = busy_reg;
118	assign error_bad_fcs = error_bad_fcs_reg;
119	
120	wire last_cycle = state_reg == STATE_LAST;
121	
122	lfsr #(
123	    .LFSR_WIDTH(32),
124	    .LFSR_POLY(32'h4c11db7),
125	    .LFSR_CONFIG("GALOIS"),
126	    .LFSR_FEED_FORWARD(0),
127	    .REVERSE(1),
128	    .DATA_WIDTH(8),
129	    .STYLE("AUTO")
130	)
131	eth_crc_8 (
132	    .data_in(last_cycle ? s_axis_tdata_d0[39:32] : s_axis_tdata[7:0]),
133	    .state_in(last_cycle ? crc_state3 : crc_state),
134	    .data_out(),
135	    .state_out(crc_next0)
136	);
137	
138	lfsr #(
139	    .LFSR_WIDTH(32),
140	    .LFSR_POLY(32'h4c11db7),
141	    .LFSR_CONFIG("GALOIS"),
142	    .LFSR_FEED_FORWARD(0),
143	    .REVERSE(1),
144	    .DATA_WIDTH(16),
145	    .STYLE("AUTO")
146	)
147	eth_crc_16 (
148	    .data_in(last_cycle ? s_axis_tdata_d0[47:32] : s_axis_tdata[15:0]),
149	    .state_in(last_cycle ? crc_state3 : crc_state),
150	    .data_out(),
151	    .state_out(crc_next1)
152	);
153	
154	lfsr #(
155	    .LFSR_WIDTH(32),
156	    .LFSR_POLY(32'h4c11db7),
157	    .LFSR_CONFIG("GALOIS"),
158	    .LFSR_FEED_FORWARD(0),
159	    .REVERSE(1),
160	    .DATA_WIDTH(24),
161	    .STYLE("AUTO")
162	)
163	eth_crc_24 (
164	    .data_in(last_cycle ? s_axis_tdata_d0[55:32] : s_axis_tdata[23:0]),
165	    .state_in(last_cycle ? crc_state3 : crc_state),
166	    .data_out(),
167	    .state_out(crc_next2)
168	);
169	
170	lfsr #(
171	    .LFSR_WIDTH(32),
172	    .LFSR_POLY(32'h4c11db7),
173	    .LFSR_CONFIG("GALOIS"),
174	    .LFSR_FEED_FORWARD(0),
175	    .REVERSE(1),
176	    .DATA_WIDTH(32),
177	    .STYLE("AUTO")
178	)
179	eth_crc_32 (
180	    .data_in(last_cycle ? s_axis_tdata_d0[63:32] : s_axis_tdata[31:0]),
181	    .state_in(last_cycle ? crc_state3 : crc_state),
182	    .data_out(),
183	    .state_out(crc_next3)
184	);
185	
186	lfsr #(
187	    .LFSR_WIDTH(32),
188	    .LFSR_POLY(32'h4c11db7),
189	    .LFSR_CONFIG("GALOIS"),
190	    .LFSR_FEED_FORWARD(0),
191	    .REVERSE(1),
192	    .DATA_WIDTH(64),
193	    .STYLE("AUTO")
194	)
195	eth_crc_64 (
196	    .data_in(s_axis_tdata[63:0]),
197	    .state_in(crc_state),
198	    .data_out(),
199	    .state_out(crc_next7)
200	);
201	
202	always @* begin
203	    state_next = STATE_IDLE;
204	
205	    reset_crc = 1'b0;
206	    update_crc = 1'b0;
207	    shift_in = 1'b0;
208	    shift_reset = 1'b0;
209	
210	    last_cycle_tkeep_next = last_cycle_tkeep_reg;
211	    last_cycle_tuser_next = last_cycle_tuser_reg;
212	
213	    s_axis_tready_next = 1'b0;
214	
215	    m_axis_tdata_int = 64'd0;
216	    m_axis_tkeep_int = 8'd0;
217	    m_axis_tvalid_int = 1'b0;
218	    m_axis_tlast_int = 1'b0;
219	    m_axis_tuser_int = 1'b0;
220	
221	    error_bad_fcs_next = 1'b0;
222	
223	    case (state_reg)
224	        STATE_IDLE: begin
225	            // idle state - wait for data
226	            s_axis_tready_next = m_axis_tready_int_early;
227	            reset_crc = 1'b1;
228	
229	            m_axis_tdata_int = s_axis_tdata_d0;
230	            m_axis_tkeep_int = s_axis_tkeep_d0;
231	            m_axis_tvalid_int = s_axis_tvalid_d0 && s_axis_tvalid;
232	            m_axis_tlast_int = 1'b0;
233	            m_axis_tuser_int = 1'b0;
234	
235	            if (s_axis_tready && s_axis_tvalid) begin
236	                shift_in = 1'b1;
237	                reset_crc = 1'b0;
238	                update_crc = 1'b1;
239	                if (s_axis_tlast) begin
240	                    if (s_axis_tkeep[7:4] == 0) begin
241	                        shift_reset = 1'b1;
242	                        reset_crc = 1'b1;
243	                        m_axis_tlast_int = 1'b1;
244	                        m_axis_tuser_int = s_axis_tuser;
245	                        m_axis_tkeep_int = {s_axis_tkeep[3:0], 4'b1111};
246	                        if ((s_axis_tkeep[3:0] == 4'b0001 && crc_valid0) ||
247	                            (s_axis_tkeep[3:0] == 4'b0011 && crc_valid1) ||
248	                            (s_axis_tkeep[3:0] == 4'b0111 && crc_valid2) ||
249	                            (s_axis_tkeep[3:0] == 4'b1111 && crc_valid3)) begin
250	                            // CRC valid
251	                        end else begin
252	                            m_axis_tuser_int = 1'b1;
253	                            error_bad_fcs_next = 1'b1;
254	                        end
255	                        s_axis_tready_next = m_axis_tready_int_early;
256	                        state_next = STATE_IDLE;
257	                    end else begin
258	                        last_cycle_tkeep_next = {4'b0000, s_axis_tkeep[7:4]};
259	                        last_cycle_tuser_next = s_axis_tuser;
260	                        s_axis_tready_next = 1'b0;
261	                        state_next = STATE_LAST;
262	                    end
263	                end else begin
264	                    state_next = STATE_PAYLOAD;
265	                end
266	            end else begin
267	                state_next = STATE_IDLE;
268	            end
269	        end
270	        STATE_PAYLOAD: begin
271	            // transfer payload
272	            s_axis_tready_next = m_axis_tready_int_early;
273	
274	            m_axis_tdata_int = s_axis_tdata_d0;
275	            m_axis_tkeep_int = s_axis_tkeep_d0;
276	            m_axis_tvalid_int = s_axis_tvalid_d0 && s_axis_tvalid;
277	            m_axis_tlast_int = 1'b0;
278	            m_axis_tuser_int = 1'b0;
279	
280	            if (s_axis_tready && s_axis_tvalid) begin
281	                shift_in = 1'b1;
282	                update_crc = 1'b1;
283	                if (s_axis_tlast) begin
284	                    if (s_axis_tkeep[7:4] == 0) begin
285	                        shift_reset = 1'b1;
286	                        reset_crc = 1'b1;
287	                        m_axis_tlast_int = 1'b1;
288	                        m_axis_tuser_int = s_axis_tuser;
289	                        m_axis_tkeep_int = {s_axis_tkeep[3:0], 4'b1111};
290	                        if ((s_axis_tkeep[3:0] == 4'b0001 && crc_valid0) ||
291	                            (s_axis_tkeep[3:0] == 4'b0011 && crc_valid1) ||
292	                            (s_axis_tkeep[3:0] == 4'b0111 && crc_valid2) ||
293	                            (s_axis_tkeep[3:0] == 4'b1111 && crc_valid3)) begin
294	                            // CRC valid
295	                        end else begin
296	                            m_axis_tuser_int = 1'b1;
297	                            error_bad_fcs_next = 1'b1;
298	                        end
299	                        s_axis_tready_next = m_axis_tready_int_early;
300	                        state_next = STATE_IDLE;
301	                    end else begin
302	                        last_cycle_tkeep_next = {4'b0000, s_axis_tkeep[7:4]};
303	                        last_cycle_tuser_next = s_axis_tuser;
304	                        s_axis_tready_next = 1'b0;
305	                        state_next = STATE_LAST;
306	                    end
307	                end else begin
308	                    state_next = STATE_PAYLOAD;
309	                end
310	            end else begin
311	                state_next = STATE_PAYLOAD;
312	            end
313	        end
314	        STATE_LAST: begin
315	            // last cycle
316	            s_axis_tready_next = 1'b0;
317	
318	            m_axis_tdata_int = s_axis_tdata_d0;
319	            m_axis_tkeep_int = last_cycle_tkeep_reg;
320	            m_axis_tvalid_int = s_axis_tvalid_d0;
321	            m_axis_tlast_int = 1'b1;
322	            m_axis_tuser_int = last_cycle_tuser_reg;
323	
324	            if ((s_axis_tkeep_d0[7:4] == 4'b0001 && crc_valid0) ||
325	                (s_axis_tkeep_d0[7:4] == 4'b0011 && crc_valid1) ||
326	                (s_axis_tkeep_d0[7:4] == 4'b0111 && crc_valid2) ||
327	                (s_axis_tkeep_d0[7:4] == 4'b1111 && crc_valid3)) begin
328	                // CRC valid
329	            end else begin
330	                m_axis_tuser_int = 1'b1;
331	                error_bad_fcs_next = 1'b1;
332	            end
333	
334	            if (m_axis_tready_int_reg) begin
335	                shift_reset = 1'b1;
336	                reset_crc = 1'b1;
337	                s_axis_tready_next = m_axis_tready_int_early;
338	                state_next = STATE_IDLE;
339	            end else begin
340	                state_next = STATE_LAST;
341	            end
342	        end
343	    endcase
344	end
345	
346	always @(posedge clk) begin
347	    if (rst) begin
348	        state_reg <= STATE_IDLE;
349	
350	        s_axis_tready_reg <= 1'b0;
351	
352	        busy_reg <= 1'b0;
353	        error_bad_fcs_reg <= 1'b0;
354	
355	        s_axis_tvalid_d0 <= 1'b0;
356	
357	        crc_state <= 32'hFFFFFFFF;
358	        crc_state3 <= 32'hFFFFFFFF;
359	    end else begin
360	        state_reg <= state_next;
361	
362	        s_axis_tready_reg <= s_axis_tready_next;
363	
364	        busy_reg <= state_next != STATE_IDLE;
365	        error_bad_fcs_reg <= error_bad_fcs_next;
366	
367	        // datapath
368	        if (reset_crc) begin
369	            crc_state <= 32'hFFFFFFFF;
370	            crc_state3 <= 32'hFFFFFFFF;
371	        end else if (update_crc) begin
372	            crc_state <= crc_next7;
373	            crc_state3 <= crc_next3;
374	        end
375	
376	        if (shift_reset) begin
377	            s_axis_tvalid_d0 <= 1'b0;
378	        end else if (shift_in) begin
379	            s_axis_tvalid_d0 <= s_axis_tvalid;
380	        end
381	    end
382	
383	    last_cycle_tkeep_reg <= last_cycle_tkeep_next;
384	    last_cycle_tuser_reg <= last_cycle_tuser_next;
385	
386	    if (shift_in) begin
387	        s_axis_tdata_d0 <= s_axis_tdata;
388	        s_axis_tkeep_d0 <= s_axis_tkeep;
389	        s_axis_tuser_d0 <= s_axis_tuser;
390	    end
391	end
392	
393	// output datapath logic
394	reg [63:0] m_axis_tdata_reg = 64'd0;
395	reg [7:0]  m_axis_tkeep_reg = 8'd0;
396	reg        m_axis_tvalid_reg = 1'b0, m_axis_tvalid_next;
397	reg        m_axis_tlast_reg = 1'b0;
398	reg        m_axis_tuser_reg = 1'b0;
399	
400	reg [63:0] temp_m_axis_tdata_reg = 64'd0;
401	reg [7:0]  temp_m_axis_tkeep_reg = 8'd0;
402	reg        temp_m_axis_tvalid_reg = 1'b0, temp_m_axis_tvalid_next;
403	reg        temp_m_axis_tlast_reg = 1'b0;
404	reg        temp_m_axis_tuser_reg = 1'b0;
405	
406	// datapath control
407	reg store_axis_int_to_output;
408	reg store_axis_int_to_temp;
409	reg store_axis_temp_to_output;
410	
411	assign m_axis_tdata = m_axis_tdata_reg;
412	assign m_axis_tkeep = m_axis_tkeep_reg;
413	assign m_axis_tvalid = m_axis_tvalid_reg;
414	assign m_axis_tlast = m_axis_tlast_reg;
415	assign m_axis_tuser = m_axis_tuser_reg;
416	
417	// enable ready input next cycle if output is ready or if both output registers are empty
418	assign m_axis_tready_int_early = m_axis_tready || (!temp_m_axis_tvalid_reg && !m_axis_tvalid_reg);
419	
420	always @* begin
421	    // transfer sink ready state to source
422	    m_axis_tvalid_next = m_axis_tvalid_reg;
423	    temp_m_axis_tvalid_next = temp_m_axis_tvalid_reg;
424	
425	    store_axis_int_to_output = 1'b0;
426	    store_axis_int_to_temp = 1'b0;
427	    store_axis_temp_to_output = 1'b0;
428	    
429	    if (m_axis_tready_int_reg) begin
430	        // input is ready
431	        if (m_axis_tready || !m_axis_tvalid_reg) begin
432	            // output is ready or currently not valid, transfer data to output
433	            m_axis_tvalid_next = m_axis_tvalid_int;
434	            store_axis_int_to_output = 1'b1;
435	        end else begin
436	            // output is not ready, store input in temp
437	            temp_m_axis_tvalid_next = m_axis_tvalid_int;
438	            store_axis_int_to_temp = 1'b1;
439	        end
440	    end else if (m_axis_tready) begin
441	        // input is not ready, but output is ready
442	        m_axis_tvalid_next = temp_m_axis_tvalid_reg;
443	        temp_m_axis_tvalid_next = 1'b0;
444	        store_axis_temp_to_output = 1'b1;
445	    end
446	end
447	
448	always @(posedge clk) begin
449	    m_axis_tvalid_reg <= m_axis_tvalid_next;
450	    m_axis_tready_int_reg <= m_axis_tready_int_early;
451	    temp_m_axis_tvalid_reg <= temp_m_axis_tvalid_next;
452	
453	    // datapath
454	    if (store_axis_int_to_output) begin
455	        m_axis_tdata_reg <= m_axis_tdata_int;
456	        m_axis_tkeep_reg <= m_axis_tkeep_int;
457	        m_axis_tlast_reg <= m_axis_tlast_int;
458	        m_axis_tuser_reg <= m_axis_tuser_int;
459	    end else if (store_axis_temp_to_output) begin
460	        m_axis_tdata_reg <= temp_m_axis_tdata_reg;
461	        m_axis_tkeep_reg <= temp_m_axis_tkeep_reg;
462	        m_axis_tlast_reg <= temp_m_axis_tlast_reg;
463	        m_axis_tuser_reg <= temp_m_axis_tuser_reg;
464	    end
465	
466	    if (store_axis_int_to_temp) begin
467	        temp_m_axis_tdata_reg <= m_axis_tdata_int;
468	        temp_m_axis_tkeep_reg <= m_axis_tkeep_int;
469	        temp_m_axis_tlast_reg <= m_axis_tlast_int;
470	        temp_m_axis_tuser_reg <= m_axis_tuser_int;
471	    end
472	
473	    if (rst) begin
474	        m_axis_tvalid_reg <= 1'b0;
475	        m_axis_tready_int_reg <= 1'b0;
476	        temp_m_axis_tvalid_reg <= 1'b0;
477	    end
478	end
479	
480	endmodule
